03125 444.2835693359375)\"> Rincón</text><line marker-end=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"110.703125\" x2=\"137.703125\" y1=\"469.2835693359375\" y2=\"469.2835693359375\"></line><line marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"137.703125\" x2=\"164.703125\" y1=\"469.2835693359375\" y2=\"469.2835693359375\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"top\" transform=\"translate(174.703125 476.2835693359375)\"> Isabela</text><line marker-end=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"110.703125\" x2=\"137.703125\" y1=\"501.2835693359375\" y2=\"501.2835693359375\"></line><line marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"137.703125\" x2=\"164.703125\" y1=\"501.2835693359375\" y2=\"501.2835693359375\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"top\" transform=\"translate(174.703125 508.2835693359375)\"> San Sebastián</text><line marker-end=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"110.703125\" x2=\"137.703125\" y1=\"533.2835693359375\" y2=\"533.2835693359375\"></line><line marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"137.703125\" x2=\"164.703125\" y1=\"533.2835693359375\" y2=\"533.2835693359375\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"top\" transform=\"translate(174.703125 540.2835693359375)\"> Ponce</text><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"105.5328125\" x2=\"163.1921875\" y1=\"206\" y2=\"213.14285714285717\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"105.5328125\" x2=\"163.1921875\" y1=\"187.42857142857144\" y2=\"204.57142857142856\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"105.5328125\" x2=\"163.1921875\" y1=\"111.7142857142857\" y2=\"134.57142857142856\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"105.5328125\" x2=\"163.1921875\" y1=\"238.85714285714286\" y2=\"268.85714285714283\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"163.1921875\" x2=\"220.8515625\" y1=\"213.14285714285717\" y2=\"203.14285714285714\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"163.1921875\" x2=\"220.8515625\" y1=\"204.57142857142856\" y2=\"228.85714285714283\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"163.1921875\" x2=\"220.8515625\" y1=\"134.57142857142856\" y2=\"183.14285714285714\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"163.1921875\" x2=\"220.8515625\" y1=\"268.85714285714283\" y2=\"256\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"220.8515625\" x2=\"278.5109375\" y1=\"203.14285714285714\" y2=\"177.42857142857144\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"220.8515625\" x2=\"278.5109375\" y1=\"228.85714285714283\" y2=\"204.57142857142856\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"220.8515625\" x2=\"278.5109375\" y1=\"183.14285714285714\" y2=\"148.85714285714283\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"220.8515625\" x2=\"278.5109375\" y1=\"256\" y2=\"240.28571428571428\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"278.5109375\" x2=\"336.1703125\" y1=\"177.42857142857144\" y2=\"204.57142857142856\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"278.5109375\" x2=\"336.1703125\" y1=\"204.57142857142856\" y2=\"208.85714285714286\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"278.5109375\" x2=\"336.1703125\" y1=\"148.85714285714283\" y2=\"140.28571428571428\"></line><line marker-end=\"url(#marker3)\" marker-start=\"url(#marker3)\" stroke=\"#999\" stroke-width=\"3.5\" x1=\"278.5109375\" x2=\"336.1703125\" y1=\"240.28571428571428\" y2=\"211.71428571428572\"></line></g></svg></figure><div aria-label=\"Long description for line graph titled Average Monthly Rainfall in Select Puerto Rican Cities from 1981 to 2010\" class=\"sr-only\" role=\"region\"><ul>\n<li>The following 4 lines are shown:\n<ul>\n<li>Rincón</li>\n<li>Isabela</li>\n<li>San Sebastián</li>\n<li>Ponce</li>\n</ul>\n</li>\n<li>The Rincón line:\n<ul>\n<li>Begins at May, 6.3 inches</li>\n<li>Falls gradually to June, 5.8 inches</li>\n<li>Rises gradually to July, 6.5 inches</li>\n<li>Rises sharply to August, 8.3 inches</li>\n<li>Falls sharply to September, 6.4 inches</li>\n</ul>\n</li>\n<li>The Isabela line:\n<ul>\n<li>Begins at May, 7.6 inches</li>\n<li>Falls gradually to June, 6.4 inches</li>\n<li>Falls gradually to July, 4.7 inches</li>\n<li>Rises gradually to August, 6.4 inches</li>\n<li>Falls gradually to September, 6.1 inches</li>\n</ul>\n</li>\n<li>The San Sebastián line:\n<ul>\n<li>Begins at May, 12.9 inches</li>\n<li>Falls gradually to June, 11.3 inches</li>\n<li>Falls sharply to July, 7.9 inches</li>\n<li>Rises sharply to August, 10.3 inches</li>\n<li>Rises gradually to September, 10.9 inches</li>\n</ul>\n</li>\n<li>The Ponce line:\n<ul>\n<li>Begins at May, 4 inches</li>\n<li>Falls sharply to June, 1.9 inches</li>\n<li>Rises gradually to July, 2.8 inches</li>\n<li>Rises gradually to August, 3.9 inches</li>\n<li>Rises gradually to September, 5.9 inches</li>\n</ul>\n</li>\n</ul></div>\n<p>A student is presenting average monthly rainfall totals in various Puerto Rican cities for a science class. During the presentation, the student notes that in September <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the graph to complete the statement?</p>","answerOptions":[{"id":"a29a271c-6bbe-4983-bc00-dc0031ae2bc4","content":"<p>Rinc&oacute;n&rsquo;s average rainfall is greater than that of Isabela, San Sebasti&aacute;n, and Ponce.</p>"},{"id":"9b5d7f0f-8b56-49b9-88c8-333c1f2e28b5","content":"<p>Rinc&oacute;n and Ponce have an average rainfall of about 5 inches, and Isabela and San Sebasti&aacute;n have an average rainfall of about 10 inches.</p>"},{"id":"77b1d0e5-663a-45f5-839c-2b7ea7ac7174","content":"<p>Rinc&oacute;n, Ponce, and Isabela each have an average rainfall below 8 inches, but San Sebasti&aacute;n&rsquo;s average rainfall that month is greater than 8 inches.</p>"},{"id":"5ecb4432-6032-4d4a-aeae-5b4dbeb8bdc9","content":"<p>Rinc&oacute;n has a similar average rainfall to Isabela, and Ponce has a similar average rainfall to San Sebasti&aacute;n.</p>"}],"keys":["77b1d0e5-663a-45f5-839c-2b7ea7ac7174"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively uses data from the graph to complete the statement about average rainfall in September in select Puerto Rican cities. The graph shows that between 1981 and 2010 Rinc&oacute;n, Ponce, and Isabela all had an average rainfall during the month of September of about 6 inches, and San Sebasti&aacute;n had an average rainfall of nearly 11 inches. Describing the average September rainfall of Rinc&oacute;n, Ponce, and Isabela as below 8 inches and the average September rainfall of San Sebasti&aacute;n as greater than 8 inches therefore offers an accurate description of the data in the graph and most effectively completes the statement. </p><p>Choice A is incorrect because it offers an inaccurate interpretation of the data in the graph. The graph shows that in September, Rinc&oacute;n, Isabela, and Ponce all have an average rainfall of about 6 inches, and San Sebasti&aacute;n has an average rainfall of nearly 11 inches. Therefore, Rinc&oacute;n&rsquo;s average rainfall is the same as, not greater than, that of Isabela and Ponce, and it is below, not greater than, that of San Sebasti&aacute;n. Choice B is incorrect because it inaccurately describes the data in the graph. In September, Rinc&oacute;n and Ponce have an average rainfall of about 6 inches, not 5 inches; Isabela has an average rainfall of about 6 inches, not 10 inches; and San Sebasti&aacute;n has an average rainfall of nearly 11 inches, not 10 inches. Choice D is incorrect because although the graph shows a similar average rainfall (about 6 inches) for Rinc&oacute;n and Isabela in September, it doesn&rsquo;t show that Ponce has a similar average rainfall to San Sebasti&aacute;n during this month. In September, Ponce&rsquo;s average rainfall is about 6 inches, whereas San Sebasti&aacute;n&rsquo;s average rainfall is nearly 11 inches. </p>","parenttemplatename":"OSP-522-QUA","parenttemplateid":"","templateclusterid":"8e4b0355-b927-4f3f-892a-48074a914e10","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959337,"updateDate":1691007959337}$SATQ$::jsonb, 1691007959337, 1691007959337),
    ($SATQ$1755eaf0$SATQ$, $SATQ$e80ca61c-04c7-47b6-bd75-6c70364e1508$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Like many other genera of wild bees, bumblebees have in recent decades experienced population collapse caused by, among other factors, habitat destruction and climate variation. Bumblebees are also one of the most researched bee genera, second only to honeybees. As a result, ecologists have gained much of their insight about wild-bee declines from bumblebees. In a <span data-ssml-say-as="date">2021</span> paper, zoologist Guillaume Ghisbain notes that bumblebees are among the relatively few wild-bee genera that display social behaviors and dietary generalism (ability to obtain nectar and pollen from a diversity of plant species), two traits that are associated with increased resilience to some specific environmental changes. Ghisbain therefore contends that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"5a5cc3f1-400e-4317-98eb-b0ac7d4f73fe","content":"<p>although bumblebees and many other wild bees have experienced similar population declines in the past, compared with other wild bees, bumblebees are likely at greater risk of being harmed by climate variation than by habitat destruction.</p>"},{"id":"b1cf7512-2bf0-4aae-8392-d4869caf167d","content":"<p>although bumblebees have been more extensively studied than most wild bees, researchers should not use bumblebees to draw conclusions about the decline of other wild bees, even ones with feeding patterns and levels of sociability that are similar to those of bumblebees.</p>"},{"id":"d7d301b3-5795-4534-bf97-4c448d3f07f1","content":"<p>because bumblebees and other bees with generalist diets are less negatively affected by environmental stress than bees with specialized diets are, they are less likely to experience major population changes in the future than bees with specialized diets are.</p>"},{"id":"bb120c92-2141-47de-b7fc-6b0d319b62e2","content":"<p>because the responses of bumblebees and other wild bees to environmental threats are not always comparable, researchers need to exercise caution when extrapolating information about wild-bee population declines from bumblebees.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["bb120c92-2141-47de-b7fc-6b0d319b62e2"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of wild-bee declines. The text establishes that bumblebees and other wild bees have been experiencing population collapse as a result of habitat destruction, climate variation, and other factors. The text then indicates that because bumblebees are very extensively researched, ecologists rely heavily on findings about them to understand wild-bee declines in general. However, the text then introduces Ghisbain&rsquo;s observation that unlike most other wild-bee genera, bumblebees have certain traits (social behaviors and dietary generalism) linked to increased resilience to certain environmental changes. In other words, bumblebees aren&rsquo;t necessarily representative of wild bees as a whole because they are likely more tolerant of some pressures. Therefore, it logically follows that Ghisbain would urge researchers to exercise caution when using bumblebee data to draw conclusions about other wild-bee population declines, since bumblebees and other wild bees don&rsquo;t always respond comparably to environmental threats.</p><p>Choice A is incorrect because the text doesn&rsquo;t indicate that climate variation is more of a threat to bumblebees than habitat destruction is or that it is a bigger threat to bumblebees than it is to other wild bees. The text simply indicates that climate variation and habitat destruction are among the factors that have caused population collapses for bumblebees and other wild-bee genera. Choice B is incorrect. As it is presented in the text, Ghisbain notes that bumblebees may respond to environmental changes differently than many other wild-bee genera do; this suggests that bumblebees shouldn&rsquo;t be treated as representative of all wild bees, but there&rsquo;s no reason to think that Ghisbain would go so far as to assert that bumblebee data shouldn&rsquo;t be used to draw conclusions about other wild-bee genera that are similar to bumblebees in their dietary and social traits, even if there are relatively few. The text suggests caution in extrapolation, not a complete rejection of using bumblebee research. Choice C is incorrect. Although the text indicates that dietary generalism is linked to increased resilience to specific environmental changes (that is, to some but not all environmental stresses), it doesn&rsquo;t suggest that bumblebees and other bees with this trait are less likely than bees with specialized diets to experience major population changes. In fact, the text makes it clear that like many other wild-bee genera&mdash;most of which don&rsquo;t display dietary generalism&mdash;bumblebees are already experiencing population collapse.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1755eaf0","external_id":"e80ca61c-04c7-47b6-bd75-6c70364e1508","vaultid":null,"uId":"18a07de0-b3bb-4e9f-80ae-9b886fe1a4a9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Like many other genera of wild bees, bumblebees have in recent decades experienced population collapse caused by, among other factors, habitat destruction and climate variation. Bumblebees are also one of the most researched bee genera, second only to honeybees. As a result, ecologists have gained much of their insight about wild-bee declines from bumblebees. In a <span data-ssml-say-as=\"date\">2021</span> paper, zoologist Guillaume Ghisbain notes that bumblebees are among the relatively few wild-bee genera that display social behaviors and dietary generalism (ability to obtain nectar and pollen from a diversity of plant species), two traits that are associated with increased resilience to some specific environmental changes. Ghisbain therefore contends that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"5a5cc3f1-400e-4317-98eb-b0ac7d4f73fe","content":"<p>although bumblebees and many other wild bees have experienced similar population declines in the past, compared with other wild bees, bumblebees are likely at greater risk of being harmed by climate variation than by habitat destruction.</p>"},{"id":"b1cf7512-2bf0-4aae-8392-d4869caf167d","content":"<p>although bumblebees have been more extensively studied than most wild bees, researchers should not use bumblebees to draw conclusions about the decline of other wild bees, even ones with feeding patterns and levels of sociability that are similar to those of bumblebees.</p>"},{"id":"d7d301b3-5795-4534-bf97-4c448d3f07f1","content":"<p>because bumblebees and other bees with generalist diets are less negatively affected by environmental stress than bees with specialized diets are, they are less likely to experience major population changes in the future than bees with specialized diets are.</p>"},{"id":"bb120c92-2141-47de-b7fc-6b0d319b62e2","content":"<p>because the responses of bumblebees and other wild bees to environmental threats are not always comparable, researchers need to exercise caution when extrapolating information about wild-bee population declines from bumblebees.</p>"}],"keys":["bb120c92-2141-47de-b7fc-6b0d319b62e2"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of wild-bee declines. The text establishes that bumblebees and other wild bees have been experiencing population collapse as a result of habitat destruction, climate variation, and other factors. The text then indicates that because bumblebees are very extensively researched, ecologists rely heavily on findings about them to understand wild-bee declines in general. However, the text then introduces Ghisbain&rsquo;s observation that unlike most other wild-bee genera, bumblebees have certain traits (social behaviors and dietary generalism) linked to increased resilience to certain environmental changes. In other words, bumblebees aren&rsquo;t necessarily representative of wild bees as a whole because they are likely more tolerant of some pressures. Therefore, it logically follows that Ghisbain would urge researchers to exercise caution when using bumblebee data to draw conclusions about other wild-bee population declines, since bumblebees and other wild bees don&rsquo;t always respond comparably to environmental threats.</p><p>Choice A is incorrect because the text doesn&rsquo;t indicate that climate variation is more of a threat to bumblebees than habitat destruction is or that it is a bigger threat to bumblebees than it is to other wild bees. The text simply indicates that climate variation and habitat destruction are among the factors that have caused population collapses for bumblebees and other wild-bee genera. Choice B is incorrect. As it is presented in the text, Ghisbain notes that bumblebees may respond to environmental changes differently than many other wild-bee genera do; this suggests that bumblebees shouldn&rsquo;t be treated as representative of all wild bees, but there&rsquo;s no reason to think that Ghisbain would go so far as to assert that bumblebee data shouldn&rsquo;t be used to draw conclusions about other wild-bee genera that are similar to bumblebees in their dietary and social traits, even if there are relatively few. The text suggests caution in extrapolation, not a complete rejection of using bumblebee research. Choice C is incorrect. Although the text indicates that dietary generalism is linked to increased resilience to specific environmental changes (that is, to some but not all environmental stresses), it doesn&rsquo;t suggest that bumblebees and other bees with this trait are less likely than bees with specialized diets to experience major population changes. In fact, the text makes it clear that like many other wild-bee genera&mdash;most of which don&rsquo;t display dietary generalism&mdash;bumblebees are already experiencing population collapse.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771170,"updateDate":1776362771170}$SATQ$::jsonb, 1776362771170, 1776362771170),
    ($SATQ$194dd448$SATQ$, $SATQ$2882f061-3de5-48d0-8c0d-bca74bb2ec3f$SATQ$::uuid, $SATQ$2d032007-7602-4fd4-994c-abf017b22084$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;John of God, the Water-Carrier&rdquo; is a 1913 short story by Mar&iacute;a Cristina Mena. In the story, the narrator presents John as being a hard worker who is fully dedicated to his job as water carrier, or <em><span lang='es'>aguador</span></em>: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;John of God, the Water-Carrier&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"dbf71dba-81df-4376-96ec-218017cfd807","content":"<p>&ldquo;Very happy, he would jog home, the heavy silver pieces in his leather pockets making a discreet and dulcet &lsquo;<em>trink-trak</em>&rsquo; between his jugs and his body.&rdquo;</p>"},{"id":"26173e0e-9cb3-4019-a4ae-c8f01f9d8a04","content":"<p>&ldquo;He learned that the city <em><span lang='es'>aguador</span></em> may not blow his whistle to halt the traffic while he gravely crosses the street, but must wait for the passing of many vehicles, some with horses and some outlandishly without.&rdquo;</p>"},{"id":"a5728c0b-ede8-44a5-a9ed-3af35edf0338","content":"<p>&ldquo;From early morn to the fall of the afternoon he would go from fountain to fountain and from portal to portal, his lean body so accustomed to bending that he never thought of straightening it, his head bowed as if in prayer.&rdquo;</p>"},{"id":"310069a0-84f1-48e9-b5b8-36d46df74ec1","content":"<p>&ldquo;When his first jugs had worn out&mdash;the sweet-scented, porous red clay becomes perforated in time&mdash;he had buried them to their necks in the corner where he slept, and they were now his treasury.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["a5728c0b-ede8-44a5-a9ed-3af35edf0338"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most effectively illustrates the claim in the text that John is hard-working and dedicated to his job. In the quotation, John is portrayed as spending &ldquo;early morn to the fall of the afternoon&rdquo; working hard as a water carrier. John is also described as &ldquo;so accustomed to bending&rdquo; while doing his work &ldquo;that he never thought of straightening&rdquo; his body, instead remaining deeply focused on his work. These details portray John as a dedicated worker. </p><p>Choice A is incorrect because this quotation portrays John as happy about heading home after being paid. It doesn&rsquo;t showcase John being hard at work. Choice B is incorrect because this quotation doesn&rsquo;t pertain to John&rsquo;s commitment to his work; it describes difficulties the traffic in the city causes John in the performance of his work. Choice D is incorrect because this quotation doesn&rsquo;t pertain to John&rsquo;s commitment to his work; it discusses what John does with his worn-out water jugs. </p>$SATQ$, false, 0, $SATQ$OSP-408-LIT$SATQ$, $SATQ$$SATQ$, $SATQ$557e93a4-eaa3-4cae-a9d1-7641d592634d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"194dd448","external_id":"2882f061-3de5-48d0-8c0d-bca74bb2ec3f","vaultid":"2d032007-7602-4fd4-994c-abf017b22084","uId":"836f57f6-b89b-4625-b6de-42b7b1aabe06","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>&ldquo;John of God, the Water-Carrier&rdquo; is a 1913 short story by Mar&iacute;a Cristina Mena. In the story, the narrator presents John as being a hard worker who is fully dedicated to his job as water carrier, or <em><span lang='es'>aguador</span></em>: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;John of God, the Water-Carrier&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"dbf71dba-81df-4376-96ec-218017cfd807","content":"<p>&ldquo;Very happy, he would jog home, the heavy silver pieces in his leather pockets making a discreet and dulcet &lsquo;<em>trink-trak</em>&rsquo; between his jugs and his body.&rdquo;</p>"},{"id":"26173e0e-9cb3-4019-a4ae-c8f01f9d8a04","content":"<p>&ldquo;He learned that the city <em><span lang='es'>aguador</span></em> may not blow his whistle to halt the traffic while he gravely crosses the street, but must wait for the passing of many vehicles, some with horses and some outlandishly without.&rdquo;</p>"},{"id":"a5728c0b-ede8-44a5-a9ed-3af35edf0338","content":"<p>&ldquo;From early morn to the fall of the afternoon he would go from fountain to fountain and from portal to portal, his lean body so accustomed to bending that he never thought of straightening it, his head bowed as if in prayer.&rdquo;</p>"},{"id":"310069a0-84f1-48e9-b5b8-36d46df74ec1","content":"<p>&ldquo;When his first jugs had worn out&mdash;the sweet-scented, porous red clay becomes perforated in time&mdash;he had buried them to their necks in the corner where he slept, and they were now his treasury.&rdquo;</p>"}],"keys":["a5728c0b-ede8-44a5-a9ed-3af35edf0338"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively illustrates the claim in the text that John is hard-working and dedicated to his job. In the quotation, John is portrayed as spending &ldquo;early morn to the fall of the afternoon&rdquo; working hard as a water carrier. John is also described as &ldquo;so accustomed to bending&rdquo; while doing his work &ldquo;that he never thought of straightening&rdquo; his body, instead remaining deeply focused on his work. These details portray John as a dedicated worker. </p><p>Choice A is incorrect because this quotation portrays John as happy about heading home after being paid. It doesn&rsquo;t showcase John being hard at work. Choice B is incorrect because this quotation doesn&rsquo;t pertain to John&rsquo;s commitment to his work; it describes difficulties the traffic in the city causes John in the performance of his work. Choice D is incorrect because this quotation doesn&rsquo;t pertain to John&rsquo;s commitment to his work; it discusses what John does with his worn-out water jugs. </p>","parenttemplatename":"OSP-408-LIT","parenttemplateid":"","templateclusterid":"557e93a4-eaa3-4cae-a9d1-7641d592634d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959336,"updateDate":1691007959336}$SATQ$::jsonb, 1691007959336, 1691007959336),
    ($SATQ$1a2b29c9$SATQ$, $SATQ$fdc309fb-203f-4eb0-ab14-ce679c48449c$SATQ$::uuid, $SATQ$eac8ab8d-78f5-438c-81ce-704840183f34$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Mar&iacute;a Cristina Mena&rsquo;s 1914 short story &ldquo;The Vine-Leaf.&rdquo;</p>
<blockquote>
<p>It is a saying in the capital of Mexico that Dr. Malsufrido carries more family secrets under his hat than any archbishop.</p>
<p>The doctor&rsquo;s hat is, appropriately enough, uncommonly capacious, rising very high, and sinking so low that it seems to be supported by his ears and eyebrows, and it has a furry look, as if it had been brushed the wrong way, which is perhaps what happens to it if it is ever brushed at all. When the doctor takes it off, the family secrets do not fly out like a flock of parrots, but remain nicely bottled up beneath a dome of old and highly polished ivory.</p>
</blockquote>$SATQ$, $SATQ$<p>Based on the text, how do people in the capital of Mexico most likely regard Dr. Malsufrido?</p>$SATQ$, $SATQ$[{"id":"1a8d26ab-988f-4870-b908-b3fafc59882b","content":"<p>Many have come to tolerate him despite his disheveled appearance.</p>"},{"id":"afc431ed-3f0c-4284-9c7b-586ea57a7bbb","content":"<p>Few feel concerned that he will divulge their confidences.</p>"},{"id":"3153160c-05c7-45ee-b626-444b8ad86678","content":"<p>Some dislike how freely he discusses his own family.</p>"},{"id":"6b6603b5-177b-4a14-b437-b83cc483cfdb","content":"<p>Most would be unimpressed by him were it not for his professional expertise.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["afc431ed-3f0c-4284-9c7b-586ea57a7bbb"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The text describes a saying in the capital that Malsufrido keeps more secrets than an archbishop. It also says that when he takes off his hat, &ldquo;the family secrets do not fly out&hellip; but remain nicely bottled up,&rdquo; suggesting that he will not betray his confidences. </p><p>Choice A is incorrect. This choice doesn&rsquo;t reflect the text. While his hat is large and appears to have been brushed in the wrong direction, Dr. Malsufrido does not seem to be regarded as ill-dressed or disheveled. Choice C is incorrect. This choice is the opposite of what the text says. The secrets of families (his and others&rsquo;) remain &ldquo;bottled up&rdquo; in his head. Choice D is incorrect. This choice isn&rsquo;t supported by the text. His professional expertise is not discussed in the passage. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CID-H001$SATQ$, $SATQ$$SATQ$, $SATQ$f4c313c0-c2f3-4672-9b82-2531a32adc39$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1a2b29c9","external_id":"fdc309fb-203f-4eb0-ab14-ce679c48449c","vaultid":"eac8ab8d-78f5-438c-81ce-704840183f34","uId":"172b75fd-0cbd-4c4e-98e9-c56f8861fd72","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The following text is adapted from Mar&iacute;a Cristina Mena&rsquo;s 1914 short story &ldquo;The Vine-Leaf.&rdquo;</p>\n<blockquote>\n<p>It is a saying in the capital of Mexico that Dr. Malsufrido carries more family secrets under his hat than any archbishop.</p>\n<p>The doctor&rsquo;s hat is, appropriately enough, uncommonly capacious, rising very high, and sinking so low that it seems to be supported by his ears and eyebrows, and it has a furry look, as if it had been brushed the wrong way, which is perhaps what happens to it if it is ever brushed at all. When the doctor takes it off, the family secrets do not fly out like a flock of parrots, but remain nicely bottled up beneath a dome of old and highly polished ivory.</p>\n</blockquote>","stem":"<p>Based on the text, how do people in the capital of Mexico most likely regard Dr. Malsufrido?</p>","answerOptions":[{"id":"1a8d26ab-988f-4870-b908-b3fafc59882b","content":"<p>Many have come to tolerate him despite his disheveled appearance.</p>"},{"id":"afc431ed-3f0c-4284-9c7b-586ea57a7bbb","content":"<p>Few feel concerned that he will divulge their confidences.</p>"},{"id":"3153160c-05c7-45ee-b626-444b8ad86678","content":"<p>Some dislike how freely he discusses his own family.</p>"},{"id":"6b6603b5-177b-4a14-b437-b83cc483cfdb","content":"<p>Most would be unimpressed by him were it not for his professional expertise.</p>"}],"keys":["afc431ed-3f0c-4284-9c7b-586ea57a7bbb"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The text describes a saying in the capital that Malsufrido keeps more secrets than an archbishop. It also says that when he takes off his hat, &ldquo;the family secrets do not fly out&hellip; but remain nicely bottled up,&rdquo; suggesting that he will not betray his confidences. </p><p>Choice A is incorrect. This choice doesn&rsquo;t reflect the text. While his hat is large and appears to have been brushed in the wrong direction, Dr. Malsufrido does not seem to be regarded as ill-dressed or disheveled. Choice C is incorrect. This choice is the opposite of what the text says. The secrets of families (his and others&rsquo;) remain &ldquo;bottled up&rdquo; in his head. Choice D is incorrect. This choice isn&rsquo;t supported by the text. His professional expertise is not discussed in the passage. </p>","parenttemplatename":"OSP-KA-CID-H001","parenttemplateid":"","templateclusterid":"f4c313c0-c2f3-4672-9b82-2531a32adc39","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959360,"updateDate":1691007959360}$SATQ$::jsonb, 1691007959360, 1691007959360),
    ($SATQ$1b9b29f1$SATQ$, $SATQ$c3302651-c023-44bf-953c-6999ac7fcd51$SATQ$::uuid, $SATQ$44b2ea80-78fa-480d-8a0e-f562236f7932$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>A team of biologists led by Jae-Hoon Jung, Antonio D. Barbosa, and Stephanie Hutin investigated the mechanism that allows <em>Arabidopsis thaliana</em> (thale cress) plants to accelerate flowering at high temperatures. They replaced the protein ELF3 in the plants with a similar protein found in another species (stiff brome) that, unlike <em>A. thaliana</em>, displays no acceleration in flowering with increased temperature. A comparison of unmodified <em>A. thaliana</em> plants with the altered plants showed no difference in flowering at 22&deg; Celsius, but at 27&deg; Celsius, the unmodified plants exhibited accelerated flowering while the altered ones did not, which suggests that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"5583c367-4907-4254-9567-fc107e6175ad","content":"<p>temperature-sensitive accelerated flowering is unique to <em>A. thaliana</em>.</p>"},{"id":"9e1022a1-c2f0-4797-bf21-70e4c89a3f84","content":"<p><em>A. thaliana&nbsp;</em>increases ELF3 production as temperatures rise.</p>"},{"id":"c24e7af8-d274-4bbc-b08d-41aa813ff5ef","content":"<p>ELF3 enables <em>A. thaliana&nbsp;</em>to respond to increased temperatures.</p>"},{"id":"1614f08f-ac56-4d17-9a1d-bf2ab2541a2b","content":"<p>temperatures of at least 22&deg; Celsius are required for <em>A. thaliana</em> to flower.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["c24e7af8-d274-4bbc-b08d-41aa813ff5ef"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of accelerated flowering in <em>A. thaliana</em> plants. The text indicates that <em>A. thaliana</em> plants show accelerated flowering at high temperatures. To investigate the mechanism for this accelerated flowering, biologists replaced the ELF3 protein in one group of <em>A. thaliana</em> plants with a similar protein found in another plant species that doesn&rsquo;t show accelerated flowering. The team then compared these modified plants to <em>A. thaliana</em> plants that retained their original ELF3 protein. The text states that the two samples of plants showed no difference in flowering at 22&deg; Celsius, but at 27&deg; Celsius the unaltered plants with ELF3 showed accelerated flowering while the plants without ELF3 didn&rsquo;t. If accelerated flowering at the higher temperature occurred in the <em>A. thaliana</em> plants with ELF3 but not in the plants without the protein, then ELF3 likely enables <em>A. thaliana</em> to respond to increased temperatures. </p><p>Choice A is incorrect because the text doesn&rsquo;t mention whether any plants other than <em>A. thaliana</em> and stiff brome show temperature-sensitive flowering, so there is no support for the idea that this type of flowering is unique to <em>A. thaliana</em>. Choice B is incorrect because the text discusses the effects of ELF3 and not the production of it. There&rsquo;s nothing in the text to suggest that the amount of ELF3 in <em>A. thaliana</em>&nbsp;varies with temperature. Choice D is incorrect. While the text states that there was no difference in the flowering of modified and unmodified <em>A. thaliana</em> plants at 22&deg; Celsius, there&rsquo;s no suggestion that <em>A. thaliana</em> only begins to flower at 22&deg; Celsius; the text doesn&rsquo;t mention a specific temperature threshold required for <em>A. thaliana </em>flowering. </p>$SATQ$, false, 0, $SATQ$OSP-009-INF$SATQ$, $SATQ$$SATQ$, $SATQ$6fd67e95-7ebb-4f94-b397-c3d9a78c4732$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1b9b29f1","external_id":"c3302651-c023-44bf-953c-6999ac7fcd51","vaultid":"44b2ea80-78fa-480d-8a0e-f562236f7932","uId":"9c096f82-ab4e-48e7-80eb-3e3a6cc6f294","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>A team of biologists led by Jae-Hoon Jung, Antonio D. Barbosa, and Stephanie Hutin investigated the mechanism that allows <em>Arabidopsis thaliana</em> (thale cress) plants to accelerate flowering at high temperatures. They replaced the protein ELF3 in the plants with a similar protein found in another species (stiff brome) that, unlike <em>A. thaliana</em>, displays no acceleration in flowering with increased temperature. A comparison of unmodified <em>A. thaliana</em> plants with the altered plants showed no difference in flowering at 22&deg; Celsius, but at 27&deg; Celsius, the unmodified plants exhibited accelerated flowering while the altered ones did not, which suggests that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"5583c367-4907-4254-9567-fc107e6175ad","content":"<p>temperature-sensitive accelerated flowering is unique to <em>A. thaliana</em>.</p>"},{"id":"9e1022a1-c2f0-4797-bf21-70e4c89a3f84","content":"<p><em>A. thaliana&nbsp;</em>increases ELF3 production as temperatures rise.</p>"},{"id":"c24e7af8-d274-4bbc-b08d-41aa813ff5ef","content":"<p>ELF3 enables <em>A. thaliana&nbsp;</em>to respond to increased temperatures.</p>"},{"id":"1614f08f-ac56-4d17-9a1d-bf2ab2541a2b","content":"<p>temperatures of at least 22&deg; Celsius are required for <em>A. thaliana</em> to flower.</p>"}],"keys":["c24e7af8-d274-4bbc-b08d-41aa813ff5ef"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of accelerated flowering in <em>A. thaliana</em> plants. The text indicates that <em>A. thaliana</em> plants show accelerated flowering at high temperatures. To investigate the mechanism for this accelerated flowering, biologists replaced the ELF3 protein in one group of <em>A. thaliana</em> plants with a similar protein found in another plant species that doesn&rsquo;t show accelerated flowering. The team then compared these modified plants to <em>A. thaliana</em> plants that retained their original ELF3 protein. The text states that the two samples of plants showed no difference in flowering at 22&deg; Celsius, but at 27&deg; Celsius the unaltered plants with ELF3 showed accelerated flowering while the plants without ELF3 didn&rsquo;t. If accelerated flowering at the higher temperature occurred in the <em>A. thaliana</em> plants with ELF3 but not in the plants without the protein, then ELF3 likely enables <em>A. thaliana</em> to respond to increased temperatures. </p><p>Choice A is incorrect because the text doesn&rsquo;t mention whether any plants other than <em>A. thaliana</em> and stiff brome show temperature-sensitive flowering, so there is no support for the idea that this type of flowering is unique to <em>A. thaliana</em>. Choice B is incorrect because the text discusses the effects of ELF3 and not the production of it. There&rsquo;s nothing in the text to suggest that the amount of ELF3 in <em>A. thaliana</em>&nbsp;varies with temperature. Choice D is incorrect. While the text states that there was no difference in the flowering of modified and unmodified <em>A. thaliana</em> plants at 22&deg; Celsius, there&rsquo;s no suggestion that <em>A. thaliana</em> only begins to flower at 22&deg; Celsius; the text doesn&rsquo;t mention a specific temperature threshold required for <em>A. thaliana </em>flowering. </p>","parenttemplatename":"OSP-009-INF","parenttemplateid":"","templateclusterid":"6fd67e95-7ebb-4f94-b397-c3d9a78c4732","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959314,"updateDate":1691007959314}$SATQ$::jsonb, 1691007959314, 1691007959314),
    ($SATQ$1ba5ad7a$SATQ$, $SATQ$0d14ed05-7101-4b7c-9ad8-f817a8ee4705$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Many literary theorists distinguish between <em>fabula</em>, a narrative&rsquo;s content, and <em>syuzhet</em>, a narrative&rsquo;s arrangement and presentation of events. In the film <em>The Godfather Part II</em>, the <em>fabula </em>is the story of the Corleone family, and the <em>syuzhet </em>is the presentation of the story as it alternates between two timelines in 1901 and 1958. But literary theorist Mikhail Bakhtin maintained that <em>fabula </em>and <em>syuzhet </em>are insufficient to completely describe a narrative&mdash;he held that systematic categorizations of artistic phenomena discount the subtle way in which meaning is created by interactions between the artist, the work, and the audience.</p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"939b7c52-2208-4eb5-99c2-0bafe31083e4","content":"<p>Literary theorist Mikhail Bakhtin argued that there are important characteristics of narratives that are not fully encompassed by two concepts that other theorists have used to analyze narratives.</p>"},{"id":"dcdd3ac8-7e11-4be5-9ddb-29a9645a2a07","content":"<p>Literary theorist Mikhail Bakhtin claimed that meaning is not inherent in a narrative but is created when an audience encounters a narrative so that narratives are interpreted differently by different people.</p>"},{"id":"c77069f8-b035-45d3-a3f3-748de097d286","content":"<p>The storytelling methods used in <em>The Godfather Part II</em> may seem unusually complicated, but they can be easily understood when two concepts from literary theory are utilized.</p>"},{"id":"1b57af45-118f-4e06-a5b2-9856b6dff2e6","content":"<p>Narratives that are told out of chronological order are more difficult for audiences to understand than are narratives presented chronologically.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["939b7c52-2208-4eb5-99c2-0bafe31083e4"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately states the main idea of the text. The text begins by explaining that many literary theorists rely on the concepts of <em>fabula</em> (a narrative&rsquo;s content) and <em>syuzhet</em> (a narrative&rsquo;s arrangement and presentation of events) and illustrates these concepts by explaining how they can be applied to the film <em>The Godfather Part II</em>. The text then discusses how Mikhail Bakhtin, a literary theorist, argued that <em>fabula</em> and <em>syuzhet</em> can&rsquo;t fully describe a narrative, since systematic categorizations such as these fail to account for all the ways in which interactions between the artist, the work, and the audience produce meaning. Thus, the main idea is that Bakhtin argued that there are important characteristics of narratives that are not fully encompassed by two concepts that other theorists have used to analyze narratives.</p><p>Choice B is incorrect because according to the text, Mikhail Bakhtin believed that meaning was created through the interactions of the artist, narrative, and audience, not simply through the interaction between the audience and narrative; moreover, the text doesn&rsquo;t address whether Bakhtin focused on the ways in which different people interpret narratives differently. Choice C is incorrect. Although the text implies that the storytelling methods used in <em>The Godfather Part II</em> are complicated, it discusses the film only to illustrate how the concepts of <em>fabula</em> and <em>syuzhet</em> may be applied to a narrative. The film&rsquo;s storytelling methods aren&rsquo;t the primary focus of the text. Choice D is incorrect. The text discusses <em>The Godfather Part II</em>, whose narrative doesn&rsquo;t adhere to a single chronological order, only to illustrate the concepts of <em>fabula </em>(a narrative&rsquo;s content) and <em>syuzhet</em> (a narrative&rsquo;s arrangement and presentation of events). The primary focus of this text isn&rsquo;t the structure of this film or of other narratives that are told out of chronological order; moreover, the text doesn&rsquo;t consider whether such structures make it harder for audiences to understand narratives.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1ba5ad7a","external_id":"0d14ed05-7101-4b7c-9ad8-f817a8ee4705","vaultid":null,"uId":"096225de-1062-4acd-b86a-5c78eaa41bfc","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Many literary theorists distinguish between <em>fabula</em>, a narrative&rsquo;s content, and <em>syuzhet</em>, a narrative&rsquo;s arrangement and presentation of events. In the film <em>The Godfather Part II</em>, the <em>fabula </em>is the story of the Corleone family, and the <em>syuzhet </em>is the presentation of the story as it alternates between two timelines in 1901 and 1958. But literary theorist Mikhail Bakhtin maintained that <em>fabula </em>and <em>syuzhet </em>are insufficient to completely describe a narrative&mdash;he held that systematic categorizations of artistic phenomena discount the subtle way in which meaning is created by interactions between the artist, the work, and the audience.</p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"939b7c52-2208-4eb5-99c2-0bafe31083e4","content":"<p>Literary theorist Mikhail Bakhtin argued that there are important characteristics of narratives that are not fully encompassed by two concepts that other theorists have used to analyze narratives.</p>"},{"id":"dcdd3ac8-7e11-4be5-9ddb-29a9645a2a07","content":"<p>Literary theorist Mikhail Bakhtin claimed that meaning is not inherent in a narrative but is created when an audience encounters a narrative so that narratives are interpreted differently by different people.</p>"},{"id":"c77069f8-b035-45d3-a3f3-748de097d286","content":"<p>The storytelling methods used in <em>The Godfather Part II</em> may seem unusually complicated, but they can be easily understood when two concepts from literary theory are utilized.</p>"},{"id":"1b57af45-118f-4e06-a5b2-9856b6dff2e6","content":"<p>Narratives that are told out of chronological order are more difficult for audiences to understand than are narratives presented chronologically.</p>"}],"keys":["939b7c52-2208-4eb5-99c2-0bafe31083e4"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately states the main idea of the text. The text begins by explaining that many literary theorists rely on the concepts of <em>fabula</em> (a narrative&rsquo;s content) and <em>syuzhet</em> (a narrative&rsquo;s arrangement and presentation of events) and illustrates these concepts by explaining how they can be applied to the film <em>The Godfather Part II</em>. The text then discusses how Mikhail Bakhtin, a literary theorist, argued that <em>fabula</em> and <em>syuzhet</em> can&rsquo;t fully describe a narrative, since systematic categorizations such as these fail to account for all the ways in which interactions between the artist, the work, and the audience produce meaning. Thus, the main idea is that Bakhtin argued that there are important characteristics of narratives that are not fully encompassed by two concepts that other theorists have used to analyze narratives.</p><p>Choice B is incorrect because according to the text, Mikhail Bakhtin believed that meaning was created through the interactions of the artist, narrative, and audience, not simply through the interaction between the audience and narrative; moreover, the text doesn&rsquo;t address whether Bakhtin focused on the ways in which different people interpret narratives differently. Choice C is incorrect. Although the text implies that the storytelling methods used in <em>The Godfather Part II</em> are complicated, it discusses the film only to illustrate how the concepts of <em>fabula</em> and <em>syuzhet</em> may be applied to a narrative. The film&rsquo;s storytelling methods aren&rsquo;t the primary focus of the text. Choice D is incorrect. The text discusses <em>The Godfather Part II</em>, whose narrative doesn&rsquo;t adhere to a single chronological order, only to illustrate the concepts of <em>fabula </em>(a narrative&rsquo;s content) and <em>syuzhet</em> (a narrative&rsquo;s arrangement and presentation of events). The primary focus of this text isn&rsquo;t the structure of this film or of other narratives that are told out of chronological order; moreover, the text doesn&rsquo;t consider whether such structures make it harder for audiences to understand narratives.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$1bf2173e$SATQ$, $SATQ$f3a1716c-52aa-429b-bdde-0271814b9d4c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In a three-year study of parasitic infections by <em>Anomotaenia brevis</em> tapeworms in <em>Temnothorax nylanderi</em> ants, entomologist Susanne Foitzik and colleagues found something unexpected: rather than reducing its host&rsquo;s fitness, as is typical of parasites, <em>A. brevis</em> greatly extends the lifespan of a <em>T. nylanderi</em> worker ant and seems to halt the effects of aging. Furthermore, those infected receive special treatment, ceasing their share of labor to sustain the colony and remaining in the nest as uninfected workers feed, groom, and transport them. By contrast, the researchers observed that uninfected workers in parasitized colonies have shortened lifespans, most likely because the <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"8c8fb5ef-5646-4710-a776-3775e2037363","content":"<p>uninfected workers are at high risk for direct exposure to <em>A. brevis</em> in the course of providing social care to the infected workers in the nest.</p>"},{"id":"5c54ef48-0288-4a14-99c1-c21556241c5a","content":"<p>need to compensate for reduced contributions within the colony while also caring for infected workers is burdensome to the uninfected workers.</p>"},{"id":"d27f6ef9-db5d-40e2-bfff-2b194e6db28c","content":"<p>high level of activity maintained by the uninfected workers makes them better able than infected workers to quickly disperse when the nest is attacked by a predator.</p>"},{"id":"927a9cbe-060d-46cb-8109-6f0dc1fda6eb","content":"<p>average lifespan of <em>T. nylanderi</em> worker ants in colonies without parasitic activity typically falls well below three years, the range covered by the study.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["5c54ef48-0288-4a14-99c1-c21556241c5a"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The text describes a study examining the relationship between a species of parasitic tapeworm, <em>A. brevis</em>, and its host insect, the <em>T. nylanderi</em> ant. According to the text, researchers were surprised to find that the tapeworm extends the life of its ant host, rather than reducing it. The text goes on to state that the infected ants end up doing less work to sustain the colony and that as a result, the uninfected ants take on the infected ants&rsquo; share of labor in addition to caring for them in their infected state. The study&rsquo;s researchers also observed that the uninfected ants have shorter lifespans than expected. If the infected ants, who are doing less work in the colony, have longer lifespans, it can be inferred that the less an ant works, the longer it will live. The opposite of this statement can also be inferred: the more an ant works, the shorter its life. So, since the workload within the colony is being redistributed so that the infected ants work less while the uninfected ants work more (as they take on the neglected duties of the infected ants and also care for those ants), then it can be inferred that the lifespans of the uninfected ants are shortened because the need to compensate for reduced contributions within the colony while also caring for infected workers is burdensome to the uninfected workers.</p><p>Choice A is incorrect because the text does not indicate how <em>A. brevis</em> is transmitted to the ants or assert that uninfected ants are more likely to be directly exposed to <em>A. brevis</em> while caring for infected ants. Choice C is incorrect because the text makes no mention of the relative abilities of infected and uninfected ants to escape predators: in fact, predators are not mentioned in the text at all. Choice D is incorrect because the text does not supply any information about the average lifespans of the ants in colonies without parasitic activity; the text only indicates factors that lengthen and shorten the lifespans of ants in parasitized colonies.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1bf2173e","external_id":"f3a1716c-52aa-429b-bdde-0271814b9d4c","vaultid":null,"uId":"5d4b56f0-8006-46ed-b94c-a21be8166069","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In a three-year study of parasitic infections by <em>Anomotaenia brevis</em> tapeworms in <em>Temnothorax nylanderi</em> ants, entomologist Susanne Foitzik and colleagues found something unexpected: rather than reducing its host&rsquo;s fitness, as is typical of parasites, <em>A. brevis</em> greatly extends the lifespan of a <em>T. nylanderi</em> worker ant and seems to halt the effects of aging. Furthermore, those infected receive special treatment, ceasing their share of labor to sustain the colony and remaining in the nest as uninfected workers feed, groom, and transport them. By contrast, the researchers observed that uninfected workers in parasitized colonies have shortened lifespans, most likely because the <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"8c8fb5ef-5646-4710-a776-3775e2037363","content":"<p>uninfected workers are at high risk for direct exposure to <em>A. brevis</em> in the course of providing social care to the infected workers in the nest.</p>"},{"id":"5c54ef48-0288-4a14-99c1-c21556241c5a","content":"<p>need to compensate for reduced contributions within the colony while also caring for infected workers is burdensome to the uninfected workers.</p>"},{"id":"d27f6ef9-db5d-40e2-bfff-2b194e6db28c","content":"<p>high level of activity maintained by the uninfected workers makes them better able than infected workers to quickly disperse when the nest is attacked by a predator.</p>"},{"id":"927a9cbe-060d-46cb-8109-6f0dc1fda6eb","content":"<p>average lifespan of <em>T. nylanderi</em> worker ants in colonies without parasitic activity typically falls well below three years, the range covered by the study.</p>"}],"keys":["5c54ef48-0288-4a14-99c1-c21556241c5a"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The text describes a study examining the relationship between a species of parasitic tapeworm, <em>A. brevis</em>, and its host insect, the <em>T. nylanderi</em> ant. According to the text, researchers were surprised to find that the tapeworm extends the life of its ant host, rather than reducing it. The text goes on to state that the infected ants end up doing less work to sustain the colony and that as a result, the uninfected ants take on the infected ants&rsquo; share of labor in addition to caring for them in their infected state. The study&rsquo;s researchers also observed that the uninfected ants have shorter lifespans than expected. If the infected ants, who are doing less work in the colony, have longer lifespans, it can be inferred that the less an ant works, the longer it will live. The opposite of this statement can also be inferred: the more an ant works, the shorter its life. So, since the workload within the colony is being redistributed so that the infected ants work less while the uninfected ants work more (as they take on the neglected duties of the infected ants and also care for those ants), then it can be inferred that the lifespans of the uninfected ants are shortened because the need to compensate for reduced contributions within the colony while also caring for infected workers is burdensome to the uninfected workers.</p><p>Choice A is incorrect because the text does not indicate how <em>A. brevis</em> is transmitted to the ants or assert that uninfected ants are more likely to be directly exposed to <em>A. brevis</em> while caring for infected ants. Choice C is incorrect because the text makes no mention of the relative abilities of infected and uninfected ants to escape predators: in fact, predators are not mentioned in the text at all. Choice D is incorrect because the text does not supply any information about the average lifespans of the ants in colonies without parasitic activity; the text only indicates factors that lengthen and shorten the lifespans of ants in parasitized colonies.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042),
    ($SATQ$1c69ff20$SATQ$, $SATQ$79f2d4f0-39de-4a51-b567-a5d51d530f5c$SATQ$::uuid, $SATQ$9599b030-9876-449d-b8e7-ec7b2f7934ce$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>For many years, the only existing fossil evidence of mixopterid eurypterids&mdash;an extinct family of large aquatic arthropods known as sea scorpions and related to modern arachnids and horseshoe crabs&mdash;came from four species living on the paleocontinent of Laurussia. In a discovery that expands our understanding of the geographical distribution of mixopterids, paleontologist Bo Wang and others have identified fossilized remains of a new mixopterid species, <em>Terropterus xiushanensis</em>, that lived over 400 million years ago on the paleocontinent of Gondwana.</p>$SATQ$, $SATQ$<p>According to the text, why was Wang and his team&rsquo;s discovery of the <em>Terropterus xiushanensis</em> fossil significant?</p>$SATQ$, $SATQ$[{"id":"b417c978-c5c9-4963-bd87-072f9984a532","content":"<p>The fossil constitutes the first evidence found by scientists that mixopterids lived more than 400 million years ago.</p>"},{"id":"293f2f91-2019-4671-894e-0be160eb812e","content":"<p>The fossil helps establish that mixopterids are more closely related to modern arachnids and horseshoe crabs than previously thought.</p>"},{"id":"f246ed9c-ba26-415c-abf8-61a0670dc33a","content":"<p>The fossil helps establish a more accurate timeline of the evolution of mixopterids on the paleocontinents of Laurussia and Gondwana.</p>"},{"id":"b5dc29f4-e386-41b6-a562-f3479f891297","content":"<p>The fossil constitutes the first evidence found by scientists that mixopterids existed outside the paleocontinent of Laurussia.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["b5dc29f4-e386-41b6-a562-f3479f891297"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it states why Wang and his team&rsquo;s discovery of the <em>Terropterus xiushanensis</em> fossil was significant. The text explains that up until Wang and his team&rsquo;s discovery, the only fossil evidence of mixopterids came from the paleocontinent of Laurussia. Wang and his team, however, identified fossil remains of a mixopterid species from the paleocontinent Gondwana. Therefore, the team&rsquo;s discovery was significant because the fossil remains of a mixopterid species were outside of the paleocontinent Laurussia. </p><p>Choice A is incorrect. Although the text states that Wang and his team identified fossilized remains of a mixopterid species that lived more than 400 million years ago, it doesn&rsquo;t indicate that mixopterid fossils previously found by scientists dated to a more recent period than that. Choice B is incorrect. Although the text states that mixopterids are related to modern arachnids and horseshoe crabs, it doesn&rsquo;t suggest that the fossil discovered by Wang and his team confirmed that this relationship is closer than scientists had previously thought.&nbsp;Choice C is incorrect because the team&rsquo;s fossil established the presence of mixopterids on Gondwana, not on Laurussia. Moreover, the text only discusses the fossil in relation to the geographical distribution of mixopterids, not in relation to their evolution. </p>$SATQ$, false, 0, $SATQ$OSP-005-CID$SATQ$, $SATQ$$SATQ$, $SATQ$1880e063-133f-4ce5-9edf-dc7244b154ab$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1c69ff20","external_id":"79f2d4f0-39de-4a51-b567-a5d51d530f5c","vaultid":"9599b030-9876-449d-b8e7-ec7b2f7934ce","uId":"49855ca8-75c5-4e3f-9a36-478189125d5f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>For many years, the only existing fossil evidence of mixopterid eurypterids&mdash;an extinct family of large aquatic arthropods known as sea scorpions and related to modern arachnids and horseshoe crabs&mdash;came from four species living on the paleocontinent of Laurussia. In a discovery that expands our understanding of the geographical distribution of mixopterids, paleontologist Bo Wang and others have identified fossilized remains of a new mixopterid species, <em>Terropterus xiushanensis</em>, that lived over 400 million years ago on the paleocontinent of Gondwana.</p>","stem":"<p>According to the text, why was Wang and his team&rsquo;s discovery of the <em>Terropterus xiushanensis</em> fossil significant?</p>","answerOptions":[{"id":"b417c978-c5c9-4963-bd87-072f9984a532","content":"<p>The fossil constitutes the first evidence found by scientists that mixopterids lived more than 400 million years ago.</p>"},{"id":"293f2f91-2019-4671-894e-0be160eb812e","content":"<p>The fossil helps establish that mixopterids are more closely related to modern arachnids and horseshoe crabs than previously thought.</p>"},{"id":"f246ed9c-ba26-415c-abf8-61a0670dc33a","content":"<p>The fossil helps establish a more accurate timeline of the evolution of mixopterids on the paleocontinents of Laurussia and Gondwana.</p>"},{"id":"b5dc29f4-e386-41b6-a562-f3479f891297","content":"<p>The fossil constitutes the first evidence found by scientists that mixopterids existed outside the paleocontinent of Laurussia.</p>"}],"keys":["b5dc29f4-e386-41b6-a562-f3479f891297"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it states why Wang and his team&rsquo;s discovery of the <em>Terropterus xiushanensis</em> fossil was significant. The text explains that up until Wang and his team&rsquo;s discovery, the only fossil evidence of mixopterids came from the paleocontinent of Laurussia. Wang and his team, however, identified fossil remains of a mixopterid species from the paleocontinent Gondwana. Therefore, the team&rsquo;s discovery was significant because the fossil remains of a mixopterid species were outside of the paleocontinent Laurussia. </p><p>Choice A is incorrect. Although the text states that Wang and his team identified fossilized remains of a mixopterid species that lived more than 400 million years ago, it doesn&rsquo;t indicate that mixopterid fossils previously found by scientists dated to a more recent period than that. Choice B is incorrect. Although the text states that mixopterids are related to modern arachnids and horseshoe crabs, it doesn&rsquo;t suggest that the fossil discovered by Wang and his team confirmed that this relationship is closer than scientists had previously thought.&nbsp;Choice C is incorrect because the team&rsquo;s fossil established the presence of mixopterids on Gondwana, not on Laurussia. Moreover, the text only discusses the fossil in relation to the geographical distribution of mixopterids, not in relation to their evolution. </p>","parenttemplatename":"OSP-005-CID","parenttemplateid":"","templateclusterid":"1880e063-133f-4ce5-9edf-dc7244b154ab","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959312,"updateDate":1691007959312}$SATQ$::jsonb, 1691007959312, 1691007959312),
    ($SATQ$1d08c7ee$SATQ$, $SATQ$b8e4991e-0fc5-4cb7-874e-6f04e764e8c9$SATQ$::uuid, $SATQ$67d5afef-da4f-4b21-ba26-a5ba9d31a8b9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Pulitzer Prize&ndash;winning writer H&eacute;ctor Tobar has built a multifaceted career as both a journalist and an author of short stories and novels. In an essay about Tobar&rsquo;s work, a student claims that Tobar blends his areas of expertise by applying journalism techniques to his creation of works of fiction.</p>$SATQ$, $SATQ$<p>Which quotation from a literary critic best supports the student&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"10dc567c-9511-43bf-b88e-305c1993a62f","content":"<p>&ldquo;For one novel, an imagined account of a real person&rsquo;s global travels, Tobar approached his subject like a reporter, interviewing people the man had met along the way and researching the man&rsquo;s own writings.&rdquo;</p>"},{"id":"7ffb7911-f427-4c37-8175-7c0a15313054","content":"<p>&ldquo;Tobar got his start as a volunteer for <em>El Tecolote</em>, a community newspaper in San Francisco, and wrote for newspapers for years before earning a degree in creative writing and starting to publish works of fiction.&rdquo;</p>"},{"id":"2a5cea7f-3999-429a-815b-8673975b0c19","content":"<p>&ldquo;Many of Tobar&rsquo;s notable nonfiction articles are marked by the writer&rsquo;s use of techniques usually associated with fiction, such as complex narrative structures and the incorporation of symbolism.&rdquo;</p>"},{"id":"db85d842-6dbc-442c-8fcb-4005dde5548e","content":"<p>&ldquo;The protagonist of Tobar&rsquo;s third novel is a man who wants to be a novelist and keeps notes about interesting people he encounters so he can use them when developing characters for his stories.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["10dc567c-9511-43bf-b88e-305c1993a62f"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The example of Tobar approaching his subject &ldquo;like a reporter,&rdquo; including conducting &ldquo;interviews&rdquo; and &ldquo;research,&rdquo; shows Tobar applying journalism techniques to his fiction-writing. </p><p>Choice B is incorrect. This choice doesn&rsquo;t support the claim. It tells us about Tobar&rsquo;s initial career as a journalist, but it doesn&rsquo;t say anything about him &ldquo;applying journalism techniques&rdquo; to his fiction-writing. Choice C is incorrect. This choice doesn&rsquo;t support the claim. It tells us that Tobar applied fiction techniques to his nonfiction writing, but we&rsquo;re looking for evidence of the other way around: that Tobar applied journalism techniques to his fiction-writing. Choice D is incorrect. This choice doesn&rsquo;t support the claim. It tells us that a character in one of Tobar&rsquo;s novels applied a journalism technique to his fiction-writing, but it doesn&rsquo;t tell us that Tobar did that himself. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-M002$SATQ$, $SATQ$$SATQ$, $SATQ$3b71dae0-5dcd-4d93-86ab-66996a97c35a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1d08c7ee","external_id":"b8e4991e-0fc5-4cb7-874e-6f04e764e8c9","vaultid":"67d5afef-da4f-4b21-ba26-a5ba9d31a8b9","uId":"a035ffe3-5549-4b06-bec9-93b99024b61a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Pulitzer Prize&ndash;winning writer H&eacute;ctor Tobar has built a multifaceted career as both a journalist and an author of short stories and novels. In an essay about Tobar&rsquo;s work, a student claims that Tobar blends his areas of expertise by applying journalism techniques to his creation of works of fiction.</p>","stem":"<p>Which quotation from a literary critic best supports the student&rsquo;s claim?</p>","answerOptions":[{"id":"10dc567c-9511-43bf-b88e-305c1993a62f","content":"<p>&ldquo;For one novel, an imagined account of a real person&rsquo;s global travels, Tobar approached his subject like a reporter, interviewing people the man had met along the way and researching the man&rsquo;s own writings.&rdquo;</p>"},{"id":"7ffb7911-f427-4c37-8175-7c0a15313054","content":"<p>&ldquo;Tobar got his start as a volunteer for <em>El Tecolote</em>, a community newspaper in San Francisco, and wrote for newspapers for years before earning a degree in creative writing and starting to publish works of fiction.&rdquo;</p>"},{"id":"2a5cea7f-3999-429a-815b-8673975b0c19","content":"<p>&ldquo;Many of Tobar&rsquo;s notable nonfiction articles are marked by the writer&rsquo;s use of techniques usually associated with fiction, such as complex narrative structures and the incorporation of symbolism.&rdquo;</p>"},{"id":"db85d842-6dbc-442c-8fcb-4005dde5548e","content":"<p>&ldquo;The protagonist of Tobar&rsquo;s third novel is a man who wants to be a novelist and keeps notes about interesting people he encounters so he can use them when developing characters for his stories.&rdquo;</p>"}],"keys":["10dc567c-9511-43bf-b88e-305c1993a62f"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The example of Tobar approaching his subject &ldquo;like a reporter,&rdquo; including conducting &ldquo;interviews&rdquo; and &ldquo;research,&rdquo; shows Tobar applying journalism techniques to his fiction-writing. </p><p>Choice B is incorrect. This choice doesn&rsquo;t support the claim. It tells us about Tobar&rsquo;s initial career as a journalist, but it doesn&rsquo;t say anything about him &ldquo;applying journalism techniques&rdquo; to his fiction-writing. Choice C is incorrect. This choice doesn&rsquo;t support the claim. It tells us that Tobar applied fiction techniques to his nonfiction writing, but we&rsquo;re looking for evidence of the other way around: that Tobar applied journalism techniques to his fiction-writing. Choice D is incorrect. This choice doesn&rsquo;t support the claim. It tells us that a character in one of Tobar&rsquo;s novels applied a journalism technique to his fiction-writing, but it doesn&rsquo;t tell us that Tobar did that himself. </p>","parenttemplatename":"OSP-KA-TXT-M002","parenttemplateid":"","templateclusterid":"3b71dae0-5dcd-4d93-86ab-66996a97c35a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959377,"updateDate":1691007959377}$SATQ$::jsonb, 1691007959377, 1691007959377),
    ($SATQ$1d0b5bf4$SATQ$, $SATQ$bacab76c-19a7-4a19-9682-f83c329bf58d$SATQ$::uuid, $SATQ$e2de97eb-326b-4b8a-bb59-79fb2929717d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>To create the poems in her 2017 collection <em>One Last Word</em>, poet Nikki Grimes used a writing method called the golden shovel. This method often involves choosing a line from an existing poem and then using each word from that line as the last word of each line in a new poem. Grimes wanted the poems in <em>One Last Word</em> to honor important Black poets of the past, so she chose lines by poets such as Langston Hughes and Georgia Douglas Johnson. Writing in this way can be challenging and might seem as though it would produce awkward poems. However, reviewers praised <em>One Last Word</em> as a beautiful and powerful tribute to the poets who inspired it. This reaction suggests that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"71c4ef7e-24e8-45db-9876-5e6ee4a81e3d","content":"<p>most reviewers didn&rsquo;t understand Grimes&rsquo;s goal for <em>One Last Word</em>.</p>"},{"id":"db9adbb9-1c3a-455f-afed-347b11a03cfb","content":"<p>Grimes successfully used the golden shovel method to achieve her goal for <em>One Last Word</em>.</p>"},{"id":"7b41fbd0-b504-4ca2-8cdf-7fa930fe71e9","content":"<p>Langston Hughes and Georgia Douglas Johnson are two of Grimes&rsquo;s favorite poets.</p>"},{"id":"338e6900-3458-4c0c-ad50-1d7ef05482d4","content":"<p>Grimes inspired many other writers to create poems using the golden shovel method.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["db9adbb9-1c3a-455f-afed-347b11a03cfb"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Nikki Grimes&rsquo;s poetry collection <em>One Last Word</em>. The text explains that Grimes used a writing method called the golden shovel to create the poems in her book. According to the text, the method involves basing a new poem on a line from an existing poem. The text then mentions Langston Hughes and Georgia Douglas Johnson as examples of important Black poets whose lines of poetry form the basis of Grimes&rsquo;s poems. The text goes on to say that this writing method is difficult and that the resulting poems can be awkward, but reviewers have positively reviewed Grimes&rsquo;s book. If the reviewers of <em>One Last Word</em> specifically note that the work is a &ldquo;beautiful and powerful tribute to the poets who inspired it,&rdquo; then they must have appreciated how Grimes used the golden shovel method to pay tribute to other poets. This suggests that Grimes was successful in using the golden shovel method to achieve her goal of honoring Black poets in her book. </p><p>Choice A is incorrect because the reaction suggests that most reviewers did understand Grimes&rsquo;s goal for her book. According to the text, the reviewers noted that the poems in her book were a &ldquo;beautiful and powerful tribute to the poets who inspired it.&rdquo; Earlier, the text claims that Grimes intended the poems &ldquo;to honor important Black poets of the past,&rdquo; so in their praise of her book, the reviewers clearly indicated that they understood Grimes&rsquo;s goal. Choice C is incorrect. Although it&rsquo;s likely that Grimes sought to honor Hughes and Johnson in her book of poetry because they&rsquo;re among her favorite poets, this fact isn&rsquo;t suggested by the reviewers&rsquo; positive reaction to her book. Instead, the reaction suggests that Grimes was successful in her use of the golden shovel method.&nbsp;Choice D is incorrect because the text doesn&rsquo;t discuss whether other writers were inspired by Grimes to use the golden shovel method in their poetry. The text mentions the poets Hughes and Johnson as examples of poets honored in Grimes&rsquo;s book and describes reviewers&rsquo; positive reception of her book, but it doesn&rsquo;t detail Grimes&rsquo;s impact on other writers. </p>$SATQ$, false, 0, $SATQ$OSP-050-INF$SATQ$, $SATQ$$SATQ$, $SATQ$0e885308-26df-4929-872b-41e9d5e8b5ea$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1d0b5bf4","external_id":"bacab76c-19a7-4a19-9682-f83c329bf58d","vaultid":"e2de97eb-326b-4b8a-bb59-79fb2929717d","uId":"cdad1e06-ca6a-48c3-91a2-3df80c6bd132","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>To create the poems in her 2017 collection <em>One Last Word</em>, poet Nikki Grimes used a writing method called the golden shovel. This method often involves choosing a line from an existing poem and then using each word from that line as the last word of each line in a new poem. Grimes wanted the poems in <em>One Last Word</em> to honor important Black poets of the past, so she chose lines by poets such as Langston Hughes and Georgia Douglas Johnson. Writing in this way can be challenging and might seem as though it would produce awkward poems. However, reviewers praised <em>One Last Word</em> as a beautiful and powerful tribute to the poets who inspired it. This reaction suggests that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"71c4ef7e-24e8-45db-9876-5e6ee4a81e3d","content":"<p>most reviewers didn&rsquo;t understand Grimes&rsquo;s goal for <em>One Last Word</em>.</p>"},{"id":"db9adbb9-1c3a-455f-afed-347b11a03cfb","content":"<p>Grimes successfully used the golden shovel method to achieve her goal for <em>One Last Word</em>.</p>"},{"id":"7b41fbd0-b504-4ca2-8cdf-7fa930fe71e9","content":"<p>Langston Hughes and Georgia Douglas Johnson are two of Grimes&rsquo;s favorite poets.</p>"},{"id":"338e6900-3458-4c0c-ad50-1d7ef05482d4","content":"<p>Grimes inspired many other writers to create poems using the golden shovel method.</p>"}],"keys":["db9adbb9-1c3a-455f-afed-347b11a03cfb"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Nikki Grimes&rsquo;s poetry collection <em>One Last Word</em>. The text explains that Grimes used a writing method called the golden shovel to create the poems in her book. According to the text, the method involves basing a new poem on a line from an existing poem. The text then mentions Langston Hughes and Georgia Douglas Johnson as examples of important Black poets whose lines of poetry form the basis of Grimes&rsquo;s poems. The text goes on to say that this writing method is difficult and that the resulting poems can be awkward, but reviewers have positively reviewed Grimes&rsquo;s book. If the reviewers of <em>One Last Word</em> specifically note that the work is a &ldquo;beautiful and powerful tribute to the poets who inspired it,&rdquo; then they must have appreciated how Grimes used the golden shovel method to pay tribute to other poets. This suggests that Grimes was successful in using the golden shovel method to achieve her goal of honoring Black poets in her book. </p><p>Choice A is incorrect because the reaction suggests that most reviewers did understand Grimes&rsquo;s goal for her book. According to the text, the reviewers noted that the poems in her book were a &ldquo;beautiful and powerful tribute to the poets who inspired it.&rdquo; Earlier, the text claims that Grimes intended the poems &ldquo;to honor important Black poets of the past,&rdquo; so in their praise of her book, the reviewers clearly indicated that they understood Grimes&rsquo;s goal. Choice C is incorrect. Although it&rsquo;s likely that Grimes sought to honor Hughes and Johnson in her book of poetry because they&rsquo;re among her favorite poets, this fact isn&rsquo;t suggested by the reviewers&rsquo; positive reaction to her book. Instead, the reaction suggests that Grimes was successful in her use of the golden shovel method.&nbsp;Choice D is incorrect because the text doesn&rsquo;t discuss whether other writers were inspired by Grimes to use the golden shovel method in their poetry. The text mentions the poets Hughes and Johnson as examples of poets honored in Grimes&rsquo;s book and describes reviewers&rsquo; positive reception of her book, but it doesn&rsquo;t detail Grimes&rsquo;s impact on other writers. </p>","parenttemplatename":"OSP-050-INF","parenttemplateid":"","templateclusterid":"0e885308-26df-4929-872b-41e9d5e8b5ea","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959324,"updateDate":1691007959324}$SATQ$::jsonb, 1691007959324, 1691007959324),
