necap="round" stroke-linejoin="round" stroke-width="0.9" x1="78.78125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="203.55555555555554" y2="203.55555555555554"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="72.78125" x2="84.78125" xmlns="http://www.w3.org/2000/svg" y1="203.55555555555554" y2="203.55555555555554"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(66.78125 209.55555555555554)">10</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="78.78125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="225.77777777777777" y2="225.77777777777777"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="72.78125" x2="84.78125" xmlns="http://www.w3.org/2000/svg" y1="225.77777777777777" y2="225.77777777777777"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(66.78125 231.77777777777777)">5</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="78.78125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="248" y2="248"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="72.78125" x2="84.78125" xmlns="http://www.w3.org/2000/svg" y1="248" y2="248"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(66.78125 254)">0</text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(24 148) rotate(-90)">Yield (pounds per acre)</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="78.78125" x2="78.78125" xmlns="http://www.w3.org/2000/svg" y1="48" y2="248"></line><rect fill="#B3B3B3" height="105.77777777777777" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="30.621875" x="109.403125" xmlns="http://www.w3.org/2000/svg" y="142.22222222222223"></rect><rect fill="#333333" height="150.2222222222222" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="30.621875" x="140.025" xmlns="http://www.w3.org/2000/svg" y="97.7777777777778"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(140.025 267.84)" x="0" xmlns="http://www.w3.org/2000/svg" y="0">2017</text><rect fill="#B3B3B3" height="140.44444444444446" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="30.621875" x="201.26874999999998" xmlns="http://www.w3.org/2000/svg" y="107.55555555555554"></rect><rect fill="#333333" height="184.44444444444446" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="30.621875" x="231.89062499999997" xmlns="http://www.w3.org/2000/svg" y="63.55555555555554"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(231.890625 267.84)" x="0" xmlns="http://www.w3.org/2000/svg" y="0">2018</text><rect fill="#B3B3B3" height="81.77777777777777" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="30.621875" x="293.134375" xmlns="http://www.w3.org/2000/svg" y="166.22222222222223"></rect><rect fill="#333333" height="120.88888888888889" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="30.621875" x="323.75624999999997" xmlns="http://www.w3.org/2000/svg" y="127.11111111111111"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(323.75624999999997 267.84)" x="0" xmlns="http://www.w3.org/2000/svg" y="0">2019</text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(231.890625 24)">Cantaloupe Yield</text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(231.890625 301.67999999999995)">Year</text><rect fill="none" height="26.84" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9" width="268.3515625" x="97.71484375" xmlns="http://www.w3.org/2000/svg" y="318.84000000000003"></rect><rect fill="#B3B3B3" height="12" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9" width="12" x="104.71484375" xmlns="http://www.w3.org/2000/svg" y="325.84000000000003"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="top" transform="translate(123.71484375 337.84000000000003)">control</text><rect fill="#333333" height="12" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9" width="12" x="194.16015625" xmlns="http://www.w3.org/2000/svg" y="325.84000000000003"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="top" transform="translate(213.16015625 337.84000000000003)">nitrogen fertilizer</text></g></svg></figure><div aria-label="Long description for bar graph titled Cantaloupe Yield" class="sr-only" role="region"><ul>
<li>For each data category, the following bars are shown:<br/>
<ul>
<li>control</li>
<li>nitrogen fertilizer</li>
</ul>
</li>
<li>The data for the 3 categories are as follows:<br/>
<ul>
<li>2017:
<ul>
<li>control: 23.8 pounds per acre</li>
<li>nitrogen fertilizer: 33.8 pounds per acre</li>
</ul>
</li>
<li>2018:
<ul>
<li>control: 31.6 pounds per acre</li>
<li>nitrogen fertilizer: 41.5 pounds per acre</li>
</ul>
</li>
<li>2019:
<ul>
<li>control: 18.4 pounds per acre</li>
<li>nitrogen fertilizer: 27.2 pounds per acre</li>
</ul>
</li>
</ul>
</li>
</ul></div>
<p>To test the effects of a nitrogen fertilizer on cantaloupe production, researchers grew cantaloupe plants and harvested their fruit over three years. In each year, half the plants were grown using a nitrogen fertilizer, and the other half were grown using a control fertilizer that contained no nitrogen. The researchers concluded that the nitrogen fertilizer increases cantaloupe yield.</p>$SATQ$, $SATQ$<p>Which choice best describes data in the graph that support the researchers&rsquo; conclusion?</p>$SATQ$, $SATQ$[{"id":"426db995-e760-4b9e-aa10-addee9247071","content":"<p>In every year of the experiment, plants treated with the nitrogen fertilizer had a yield of at least 30 pounds per acre.</p>"},{"id":"0ad64279-bf41-47ef-874d-03d74f2ecb7b","content":"<p>In every year of the experiment, plants treated with the nitrogen fertilizer had a greater yield than did plants treated with the control fertilizer.&nbsp;</p>"},{"id":"23ed994e-d2d6-46ea-83ff-f374e860e1cb","content":"<p>The 2018 yield for plants treated with the control fertilizer was greater than was the 2019 yield for plants treated with the nitrogen fertilizer.&nbsp;</p>"},{"id":"ebd00eff-b80a-4e1a-9ffa-537d744717e9","content":"<p>The yield for plants treated with the nitrogen fertilizer increased from 2017 to 2018.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["0ad64279-bf41-47ef-874d-03d74f2ecb7b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it describes data from the graph that support the researchers&rsquo; conclusion that using nitrogen fertilizer increases cantaloupe production. The bar graph shows the cantaloupe yield for plants grown with nitrogen fertilizer and for those grown with a control fertilizer (without nitrogen) for three consecutive years (2017&ndash;2019). For each year in the graph, the yield for the nitrogen group is greater than the yield for the control group. In pounds per acre, the value in 2017 for the nitrogen-group yield is greater than 30 while the control-group yield is less than 25; in 2018 the nitrogen-group yield is greater than 40 while the control-group yield is less than 35; and in 2019 the nitrogen-group yield is greater than 25 while the control-group yield is less than 20. Thus, these data from the graph strongly support the conclusion that using nitrogen fertilizer increases cantaloupe yield. </p><p>Choice A is incorrect because the bar graph shows that in 2019 the nitrogen group had a yield below 30 pounds per acre. Choice C is incorrect. Although this choice accurately describes data in the bar graph&mdash;in 2018, the control-group yield is greater than 30 pounds per acre, and in 2019 the nitrogen-group yield is less than 30 pounds per acre&mdash;a claim that the control-group yield exceeds that of the nitrogen group strongly conflicts with the researchers&rsquo; conclusion that nitrogen fertilizer produces larger yields. Choice D is incorrect. Although it is true that the bar graph shows a higher yield for the nitrogen group in 2018 than in 2017, without the control to compare against, it is impossible to know whether the increase is due to the fertilizer and not, for example, more favorable weather in 2018 than in 2017.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-500-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$cbcd3283-5a52-49b4-92f8-4e1b93274279$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1db1a9a6","external_id":"aa6c4390-0a98-4e87-80f3-b711067988be","vaultid":"bfdb848e-1eb5-44cc-9188-7414e02771bb","uId":"b48f18ed-c4d5-4c55-b7d2-9efc2d94ff75","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<figure class=\"image\"><svg aria-label=\"Bar graph titled Cantaloupe Yield. The horizontal axis is labeled Year. 3 data categories are shown. The vertical axis is labeled Yield, in pounds per acre. It ranges from 0 to 45 in increments of 5. Refer to long description.\" height=\"356.6800268554687\" role=\"img\" viewbox=\"0 0 400 356.6800268554687\" width=\"400\" xmlns=\"http://www.w3.org/2000/svg\"><g data-name=\"Layer 1\" id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\"><defs>\n<pattern height=\"100\" id=\"bar4\" patterntransform=\"rotate(50)\" patternunits=\"userSpaceOnUse\" width=\"10\" x=\"0\" y=\"0\">\n<rect fill=\"#CDCDCD\" height=\"100\" width=\"5\" x=\"0\" y=\"0\"></rect>\n<rect fill=\"#444444\" height=\"100\" width=\"5\" x=\"5\" y=\"0\"></rect>\n</pattern>\n</defs><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"78.78125\" x2=\"385\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"48\" y2=\"48\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"72.78125\" x2=\"84.78125\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"48\" y2=\"48\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(66.78125 54)\">45</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"78.78125\" x2=\"385\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"70.22222222222223\" y2=\"70.22222222222223\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"72.78125\" x2=\"84.78125\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"70.22222222222223\" y2=\"70.22222222222223\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(66.78125 76.22222222222223)\">40</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"78.78125\" x2=\"385\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"92.44444444444444\" y2=\"92.44444444444444\"></line><lin